'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const A='/assets/';let BLOCKS=[];const PRODUCTS=[...window.PLATFORM_PRODUCTS,...window.PRODUCTS];const ROUTE=decodeURI(location.pathname).replace(/\/$/,'')||'/';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,text,cls='text-link')=>`<a class="${cls}" href="${url}" ${url.startsWith('https:')?'target="_blank" rel="noopener"':''}>${text} ↗</a>`;
let art=(name,cls='sculpture',alt='Composição geométrica de capacidades Catalisa')=>`<img class="${cls}" src="${A+name}.svg" alt="${alt}" loading="lazy">`;
const eyebrow=t=>`<div class="eyebrow">${t}</div>`;
const head=(n,title,desc='')=>`<div class="section-head"><div>${eyebrow(n)}<h2>${title}</h2></div>${desc?`<p>${desc}</p>`:''}</div>`;
const section=(body,cls='')=>`<section class="section ${cls}"><div class="container">${body}</div></section>`;
const actions=(a,b='')=>`<div class="actions">${a}${b}</div>`;
const source=(url,label='Conteúdo baseado na fonte oficial')=>`<div class="source-note">${label}. ${link(url,'Consultar a fonte','')}</div>`;
const rows=items=>`<div class="rules">${items.map((x,i)=>`<div class="rule-row"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`;
const steps=items=>`<div class="steps">${items.map(x=>`<div class="step"><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div>`;
const blockLink=b=>`/capacidades/${b.slug}/`;
let blockTile=b=>`<a class="tile" href="${blockLink(b)}"><span class="arrow">↗</span>${art(b.art,'','')}${eyebrow(b.category)}<h3>${esc(b.name)}</h3><p>${esc(b.tagline)}</p><div style="margin-top:18px" class="status ${b.status.toLowerCase()}">${esc(b.status)}</div></a>`;
const blocksSelected=(slugs,cls='grid4')=>`<div class="${cls}">${slugs.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div>`;
let productCard=p=>`<a class="product-card" href="/ecossistema/${p.slug}/">${eyebrow(p.category)}<div class="art-wrap">${art(p.art,'',p.name+' — composição conceitual')}</div><h3>${p.title}</h3><p>${p.description}</p><span class="domain">${p.domainLabel||p.domainLabel||p.slug+'.catalisa.app'} ↗</span></a>`;
let hero=(tag,title,desc,visual='')=>`<section class="hero"><div class="container">${visual?`<div class="hero-split"><div>${eyebrow(tag)}<h1>${title}</h1><p class="lead">${desc}</p></div>${art(visual,'hero-art')}</div>`:`<div class="hero-text">${eyebrow(tag)}<h1>${title}</h1><p class="lead">${desc}</p></div>`}</div></section>`;
const flow=nodes=>`<div class="flow" aria-label="Fluxo ilustrativo">${nodes.map((x,i)=>`${i?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-node ${i===nodes.length-2?'selected':''}">${x}</div>`).join('')}</div>`;
const faq=items=>`<div class="faq">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div>`;
const compositionData=[{name:'Atendimento',title:'Uma conversa conecta várias capacidades.',text:'O canal recebe a mensagem, a IA trabalha com o contexto da organização e a agenda oferece horários reais. O registro acompanha a interação.',blocks:['wpp-business','ai-engine','calendar','customers'],art:'med',nodes:['Mensagem','Contexto','Agenda','Registro']},{name:'Identidade',title:'Verificar é uma composição.',text:'Uma sessão recebe a captura, aplica a política de verificação e entrega o resultado com a evidência. Arquivos e eventos têm responsabilidades próprias.',blocks:['biometrics','file-storage','webhooks-engine','api-keys'],art:'biometrics',nodes:['Sessão','Captura','Verificação','Evidência']},{name:'Decisão',title:'Dados e regras têm papéis diferentes.',text:'A esteira reúne as fontes declaradas. O motor aplica a política versionada. A execução registra o caminho até a resposta.',blocks:['decision-platform','decision-engine','bureaus','iam'],art:'decision',nodes:['Entrada','Fontes','Política','Resposta']},{name:'Documentos',title:'O documento também tem uma jornada.',text:'Um template organiza as variáveis. O documento gerado é armazenado, enviado para assinatura e acompanhado por eventos.',blocks:['document-template','file-storage','e-signature','webhooks-engine'],art:'document',nodes:['Template','Documento','Assinatura','Evento']}];
function composition(){return `<div data-composition><div class="tabs" role="tablist" aria-label="Composições">${compositionData.map((x,i)=>`<button class="tab" role="tab" aria-selected="${!i}" data-comp="${i}">${x.name}</button>`).join('')}</div><div id="composition-panel" role="tabpanel"></div></div>`}
function bindComposition(){const el=$('[data-composition]');if(!el)return;const show=i=>{const d=compositionData[i];$$('[data-comp]',el).forEach(b=>b.setAttribute('aria-selected',Number(b.dataset.comp)===i));$('#composition-panel').innerHTML=`<div class="composition appear">${art(d.art)}<div>${eyebrow('Composição ilustrativa · baseada no catálogo')}<h3>${d.title}</h3><p>${d.text}</p>${flow(d.nodes)}<div class="tag-list">${d.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(b=>`<a class="tag" href="${blockLink(b)}">${b.name} ↗</a>`).join('')}</div></div></div>`};$$('[data-comp]',el).forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.comp))));show(0)}
function header(){const nav=[['/visao/','Visão'],['/arquitetura/','Arquitetura'],['/capacidades/','Capacidades'],['/ecossistema/','Ecossistema'],['/perspectivas/','Perspectivas']];return `<a class="skip" href="#main">Pular para o conteúdo</a><div class="review-banner">Proposta de marca · versão para avaliação <a href="/mapa/">Ver todas as páginas ↗</a></div><header><div class="container header-inner"><a class="logo" href="/" aria-label="Catalisa — início"><img class="official-logo" src="/assets/logo.svg" alt="Catalisa" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><span hidden>catalisa<i></i></span></a><nav id="navigation" class="nav" aria-label="Principal">${nav.map(([u,n])=>`<a href="${u}" class="${ROUTE.startsWith(u.slice(0,-1))?'active':''}" ${ROUTE===u.slice(0,-1)?'aria-current="page"':''}>${n}</a>`).join('')}</nav><a class="contact-link" href="/contato/">Vamos conversar ↗</a><button class="menu-button" aria-controls="navigation" aria-expanded="false" aria-label="Abrir menu">☰</button></div></header>`}
function footer(){return `<div class="footer-cta"><div class="container"><h2>O próximo começa<br>com uma boa base.</h2>${link('/contato/','Vamos conversar','button')}</div></div><footer class="footer"><div class="container"><div class="footer-top"><div><a class="logo" href="/">catalisa<i></i></a><p style="margin-top:20px">Uma plataforma de capacidades combináveis. Diferentes produtos. Uma arquitetura comum.</p></div><div><h4>Explore a base</h4><a href="/visao/">Visão</a><a href="/arquitetura/">Arquitetura</a><a href="/capacidades/">Building blocks</a><a href="/composicoes/">Composições</a><a href="/governanca/">Governança</a></div><div><h4>Construa</h4><a href="/studio/">Studio</a><a href="/workflows/">Workflows</a><a href="/agentes/">Agentes IA</a><a href="/desenvolvedores/">Desenvolvedores</a><a href="/ecossistema/">Ecossistema</a></div><div><h4>Marca e recursos</h4><a href="/perspectivas/">Perspectivas</a><a href="/press-kit/">Press-kit</a><a href="/contato/">Contato</a><a href="/fontes/">Fontes e conteúdo</a><a href="/mapa/">Todas as páginas</a></div></div><div class="footer-bottom"><span>© 2026 Catalisa · Proposta para avaliação</span><span>Conteúdo baseado nos sites e na documentação pública · 15 out 2026</span><span><a href="https://catalisa.io/privacidade" target="_blank" rel="noopener">Privacidade no site oficial ↗</a></span></div></div></footer>`}
function home(){return `<section class="hero"><div class="container"><div class="hero-text">${eyebrow('Catalisa / Plataforma de tecnologia composable')}<h1>Dê forma ao<br>que vem depois.</h1><p class="lead">Da complexidade à construção. Capacidades que se combinam para criar produtos, conectar operações e abrir novas possibilidades.</p>${actions(link('/arquitetura/','Explore a arquitetura','button outline'),link('/ecossistema/','Conheça o ecossistema'))}</div><img src="/assets/hero-architecture.png" class="wide-art" alt="Linhas e peças dispersas se organizam em uma arquitetura modular roxa, branca e amarela" fetchpriority="high"><div class="hero-bottom"><span class="mono">01 / Organizar</span><span class="mono">02 / Compor</span><span class="mono">03 / Materializar</span></div></div></section>`+section(`<div class="grid2"><h2>Uma base.<br>Infinitas composições.</h2><div><p class="lead">Identidade, comunicação, dados, decisão, documentos e inteligência. Na Catalisa, capacidades com responsabilidades próprias se conectam para formar soluções completas.</p>${link('/visao/','Entenda a nossa visão')}</div></div>`)+section(`<div class="grid2">${art('stack')}<div>${eyebrow('01 / Arquitetura composable')}<h2>Capacidades que<br>se combinam.</h2><p>A plataforma reúne building blocks com identidade, permissões e isolamento compartilhados. Cada bloco cuida de um domínio; a composição conecta esses domínios ao que o negócio precisa.</p>${rows([['Identidade','Quem participa, em qual organização e com quais permissões.'],['Dados e regras','Fontes conectadas e políticas de negócio versionadas.'],['Experiência','Canais, documentos, vídeo e automações em uma jornada.']])}${actions(link('/arquitetura/','Veja a arquitetura'))}</div></div>`)+section(head('02 / Composição','A mesma base.<br>Novas possibilidades.','Explore exemplos de como as capacidades se conectam. Cada bloco leva à sua página de conteúdo real.')+composition())+section(head('03 / Capacidades','Peças com propósito.','Um recorte do catálogo técnico. Consulte o estágio e o escopo de cada capacidade.')+blocksSelected(['iam','decision-engine','rooms','webhooks-engine'])+actions(link('/capacidades/','Explore todos os building blocks')))+section(head('04 / Ecossistema','Construído com Catalisa.','Banking, crédito, saúde, advocacia, recrutamento, identidade e decisão: expressões de uma base comum.')+`<div class="products-grid">${PRODUCTS.slice(0,3).map(productCard).join('')}</div>`+actions(link('/ecossistema/','Explore todos os produtos')))+section(`<div class="grid2"><div>${eyebrow('05 / Da intenção à execução')}<h2>Ideias encontram<br>uma forma de operar.</h2><p>O Studio transforma linguagem natural em especificações e fluxos. Workflows conectam capacidades. Agentes trabalham com contexto e ferramentas.</p>${rows([['Studio','Descreva e refine o que você quer construir.'],['Workflows','Organize eventos, condições e ações.'],['Agentes','Conecte conversa, conhecimento e execução.']])}</div>${art('orbit')}</div>`,'purple')+section(screenFeature())+section(head('06 / Perspectivas','Construir também<br>é uma forma de pensar.')+articleCards())}
function vision(){return hero('Visão / A ideia por trás da base','Construir é<br>compor.','A Catalisa organiza capacidades de tecnologia para que novos produtos não precisem começar sempre do mesmo ponto.','signal')+section(`<div class="editorial"><p>A complexidade de uma operação não desaparece quando uma nova interface entra no ar. Ela continua nos dados, nas regras, nas integrações e nas decisões que sustentam cada interação.</p><p>A proposta da Catalisa é dar a essas responsabilidades uma forma que possa ser entendida, combinada e reutilizada.</p></div>`)+section(rows([['Capacidades com fronteiras','Uma regra de negócio, uma sessão de vídeo e uma assinatura têm contratos e ciclos próprios.'],['Composição como método','Conectar essas capacidades permite construir jornadas específicas para cada contexto.'],['Produtos como expressão','Med, Jurídico, Recrutamento, Biometrics e Decision materializam essa base em necessidades concretas.']]))+section(`<div class="poster"><div class="poster-copy">${eyebrow('Uma arquitetura, muitos contextos')}<h2>A próxima forma<br>não precisa<br>começar do zero.</h2>${link('/ecossistema/','Explore o ecossistema')}</div><div class="poster-art">${art('modules')}</div></div>`)+section(head('Princípios','O que dá consistência<br>à construção.')+rows([['Clareza','Uma capacidade precisa explicar o que faz e onde termina.'],['Reuso','A mesma base pode participar de produtos diferentes.'],['Responsabilidade','Automação e decisão humana têm papéis explícitos nos produtos.'],['Evidência','Versões, registros e contratos tornam o comportamento observável.']])+source('https://docs.catalisa.app/blocks/'))}
function architecture(){return hero('Arquitetura / Capacidades conectadas','A estrutura<br>do possível.','Building blocks com responsabilidades próprias. Uma linguagem comum de identidade, permissões e isolamento.','stack')+section(`<div class="grid2"><div>${eyebrow('A base compartilhada')}<h2>O que é comum<br>não precisa se repetir.</h2><p>O catálogo público descreve um modelo de identidade compartilhado, um vocabulário comum de permissões e isolamento entre organizações. Essa base sustenta capacidades de domínios diferentes.</p>${link('/capacidades/iam/','Conheça o IAM')}</div>${rows([['Identidade','O token identifica usuário, organização e permissões.'],['Contratos','APIs e eventos definem como cada bloco participa da integração.'],['Domínios','Regras, arquivos, comunicação e dados preservam suas responsabilidades.'],['Composição','Workflows e produtos conectam os blocos em jornadas.']])}</div>`)+section(head('As responsabilidades','Uma composição,<br>vista por dentro.','As ilustrações ajudam a ler a composição. Elas não representam uma topologia literal de implantação.')+composition())+section(`<div class="grid2">${art('decision')}<div>${eyebrow('Um exemplo real / Decisão')}<h2>A esteira busca.<br>O motor decide.</h2><p>O Decision Platform reúne as fontes declaradas. O Decision Engine avalia a política DMN publicada. A separação permite evoluir integração de dados e regra de negócio com responsabilidades claras.</p>${actions(link('/capacidades/decision-platform/','Explore a esteira'),link('/capacidades/decision-engine/','Explore o motor'))}</div></div>`)+section(head('Camadas de construção','Da capacidade à experiência.')+rows([['Building blocks','IAM, Calendar, Rooms, Data Store, E-Signature e outros blocos expõem capacidades por contrato.'],['Orquestração','Workflows ligam eventos, condições e ações para executar uma jornada.'],['Agentes e interfaces','Conversas e aplicações dão acesso às capacidades com contexto.'],['Produtos','As verticais adaptam a composição ao trabalho de cada setor.']])+source('https://docs.catalisa.app/blocks/'))+section(`<div class="grid2"><div><h2>Uma arquitetura<br>também declara limites.</h2><p>O catálogo diferencia Produção, Beta e Alpha. Cada página apresenta o estágio documentado e os limites publicados, sem transformar planos futuros em funcionalidades disponíveis.</p>${link('/governanca/','Veja governança e responsabilidade')}</div>${art('document')}</div>`,'purple')}
function catalog(){return hero('Catálogo / Capacidades','Peças independentes.<br>Uma linguagem comum.','Explore o catálogo público de building blocks. Busque por capacidade, navegue por domínio e consulte o estágio de cada módulo.')+section(`<div class="toolbar"><input type="search" id="block-search" class="search" placeholder="Buscar capacidade, domínio ou descrição…" aria-label="Buscar capacidades"><select id="block-category" aria-label="Filtrar por domínio"><option value="">Todos os domínios</option>${[...new Set(BLOCKS.map(b=>b.category))].sort().map(x=>`<option>${x}</option>`).join('')}</select><select id="block-status" aria-label="Filtrar por estágio"><option value="">Todos os estágios</option><option>Produção</option><option>Beta</option><option>Alpha</option></select></div><div class="catalog-count" id="catalog-count" role="status"></div><div class="catalog-grid" id="catalog-results"></div>${source('https://docs.catalisa.app/blocks/','Descrições e estágios consultados no catálogo técnico público em 15/10/2026')}`)}
function bindCatalog(){if(!$('#block-search'))return;function update(){const q=$('#block-search').value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const c=$('#block-category').value,s=$('#block-status').value;const results=BLOCKS.filter(b=>(!c||c===b.category)&&(!s||s===b.status)&&(!q||`${b.name} ${b.category} ${b.tagline}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)));$('#catalog-count').textContent=`${results.length} de ${BLOCKS.length} building blocks`;$('#catalog-results').innerHTML=results.length?results.map(blockTile).join(''):'<div class="empty"><h3>Nenhuma capacidade encontrada.</h3><p>Tente outro termo ou remova os filtros.</p><button class="button outline" id="clear-filters">Limpar filtros</button></div>';$('#clear-filters')?.addEventListener('click',()=>{$('#block-search').value='';$('#block-category').value='';$('#block-status').value='';update()})}['block-search','block-category','block-status'].forEach(id=>$('#'+id).addEventListener(id==='block-search'?'input':'change',update));update()}
function blockPage(b){return `<div class="container"><div class="breadcrumb"><a href="/capacidades/">Capacidades</a><span>/</span><span>${b.category}</span><span>/</span><span>${b.name}</span></div><div class="detail-banner"><div class="detail-intro">${eyebrow(b.category+' / Building block')}<h1>${b.name}</h1><p class="lead">${b.tagline}</p><div class="status ${b.status.toLowerCase()}">${b.status} · estágio na documentação pública</div>${actions(link(b.source,'Documentação técnica','button outline'))}</div>${art(b.art)}</div></div>`+section(`<div class="doc-layout"><aside class="toc">${eyebrow('Nesta capacidade')}${b.sections.map(x=>`<a href="#${x.id}">${x.title}</a>`).join('')}<a href="${b.source}" target="_blank" rel="noopener">Referência completa ↗</a></aside><div>${b.sections.length?b.sections.map(x=>`<section class="doc-section" id="${x.id}"><h2>${x.title}</h2>${x.html}</section>`).join(''):`<p>${b.tagline}</p>`}${source(b.source,'Trechos editoriais da documentação oficial; contrato, rotas, limites e atualizações permanecem na referência completa')}</div></div>`)+section(head('Continue a composição','Capacidades relacionadas.')+`<div class="grid3">${BLOCKS.filter(x=>x.category===b.category&&x.slug!==b.slug).slice(0,3).map(blockTile).join('')||BLOCKS.filter(x=>x.slug!==b.slug).slice(0,3).map(blockTile).join('')}</div>`)}
function ecosystem(){return hero('Ecossistema / Construído com Catalisa','A mesma base.<br>Diferentes realidades.','Produtos que aplicam capacidades compartilhadas a contextos específicos. Explore o trabalho que cada um organiza e a arquitetura que pode participar dessa composição.','modules')+section(PRODUCTS.map((p,i)=>`<div class="wide-product"><div class="product-image">${art(p.art,'',p.name+' — ilustração conceitual')}</div><div>${eyebrow(String(i+1).padStart(2,'0')+' / Catalisa '+p.name+' / '+p.category)}<h2>${p.title}</h2><p>${p.description}</p>${actions(link('/ecossistema/'+p.slug+'/','Conheça a composição','button outline'),link(p.source,'Visite o produto'))}</div></div>`).join(''))+section(`<div class="editorial"><h2>Os produtos mudam.<br>A capacidade permanece.</h2><p>Uma sala de vídeo pode apoiar uma consulta, uma entrevista ou uma conversa jurídica. Uma agenda coordena pessoas em contextos diferentes. Identidade, documentos e regras continuam sendo capacidades da plataforma.</p>${link('/composicoes/','Veja como os blocos se conectam')}</div>`)}
function productPage(p){if(['banking','credit'].includes(p.slug))return platformPage(p);return hero('Ecossistema / Catalisa '+p.name,p.headline,p.description,p.art)+section(`<div class="grid2"><div>${eyebrow('A proposta do produto')}<h2>${p.principle}</h2><p>${p.principleText}</p>${actions(link(p.source,'Explore o produto oficial','button outline'))}</div>${p.slug==='med'?`<div class="compare"><div class="document">${eyebrow('Rascunho da IA')}<div class="line"></div><div class="line"></div><div class="line"></div><div class="signature" style="opacity:.4">Aguardando revisão</div></div><div class="document signed">${eyebrow('Liberado pelo profissional')}<div class="line"></div><div class="line"></div><div class="line"></div><div class="signature">Revisado ✓</div></div></div>`:art(p.slug==='decision'?'signal':p.slug==='juridico'?'document':p.slug==='recrutamento'?'orbit':'biometrics')}</div>`)+section(head('A jornada','O trabalho, passo a passo.')+`<div class="grid2">${steps(p.steps)}<div>${art(p.art)}<p class="small-note">Representação conceitual da jornada descrita no produto.</p></div></div>`)+section(head('Capacidades em contexto','O que esta solução organiza.')+rows(p.features))+section(head('A base por trás da experiência','Peças que ajudam<br>a entender a composição.','Seleção conceitual de capacidades relacionadas ao produto. Consulte os contratos e estágios de cada bloco; esta seleção não é um inventário de implantação.')+`<div class="grid3">${p.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div>`)+section(`<div class="grid2"><div><h2>Autonomia com<br>responsabilidade.</h2><p>${p.boundary}</p></div><div>${source(p.source,'Resumo baseado no conteúdo público do produto')}${link(p.source,'Veja detalhes, demonstrações e condições no produto')}</div></div>`,'')+section(head('Outras expressões da mesma base','Continue pelo ecossistema.')+`<div class="products-grid">${PRODUCTS.filter(x=>x.slug!==p.slug).slice(0,3).map(productCard).join('')}</div>`)}
const ESSAYS=[
{slug:'construir-por-composicao',title:'Construir por composição.',tag:'Arquitetura',art:'stair',desc:'Como capacidades independentes podem participar de experiências diferentes.',source:'https://docs.catalisa.app/blocks/',body:`<p>Uma agenda não pertence apenas a uma clínica. Uma sala de vídeo não pertence apenas a uma entrevista. Uma assinatura não pertence apenas a um contrato de crédito. Quando essas responsabilidades se tornam capacidades com contrato, podem participar de produtos diferentes.</p><h2>A capacidade tem um papel.</h2><p>O catálogo da Catalisa separa identidade, comunicação, dados, decisão, documentos, financeiro e inteligência. Cada bloco descreve o trabalho que executa, o estágio em que está e a forma de integrá-lo.</p><p>O Calendar reúne agendas e disponibilidade. O Rooms cria a experiência de vídeo com gravação e transcrição. O E-Signature acompanha a coleta de assinatura. O IAM organiza identidade e permissões para o conjunto.</p><h2>O produto dá contexto à composição.</h2><p>Em Med, agenda e vídeo participam do atendimento e da consulta. Em Recrutamento, participam da entrevista. Em Jurídico, organizam a consulta e o acesso ao conhecimento do escritório. A experiência muda porque a necessidade muda.</p><h2>Compartilhar exige uma base comum.</h2><p>A documentação descreve um modelo de identidade, um vocabulário de permissões e isolamento entre organizações compartilhados pelos building blocks. Esse contrato comum evita tratar cada integração como um mundo independente.</p><p>Compor também exige conhecer limites. Alpha, Beta e Produção indicam estágios diferentes. Um catálogo útil mostra essas diferenças e permite aprofundar o que cada peça faz.</p>`},
{slug:'regra-legivel',title:'O valor de uma regra legível.',tag:'Decisão',art:'decision',desc:'Quando a política sai do código, versão e evidência passam a fazer parte da conversa.',source:'https://docs.catalisa.app/blocks/decision-engine/',body:`<p>Uma política de negócio muda por decisão comercial, por aprendizado operacional ou por uma nova exigência. Quando essa política fica escondida em condicionais do aplicativo, a mudança percorre o processo de software inteiro.</p><h2>A regra se torna um objeto.</h2><p>O Decision Engine representa políticas como tabelas de decisão DMN. Entradas, condições e saídas ficam em um formato próprio para expressar regras determinísticas. A tabela é versionada e sua publicação é uma ação explícita.</p><p>A aplicação continua chamando o motor. A política pode ganhar uma nova versão sem que o consumidor precise mudar sua integração.</p><h2>A execução precisa lembrar.</h2><p>A documentação descreve logs com entrada, saída, versão usada e tempo de execução. O histórico permite consultar qual política avaliou uma proposta, em vez de reconstruir o comportamento a partir de código antigo.</p><h2>Buscar dados e aplicar regra são trabalhos diferentes.</h2><p>O Decision Platform reúne as fontes declaradas e chama o Decision Engine para avaliar a política. Essa separação preserva o papel de cada capacidade: uma organiza os dados; a outra aplica a regra.</p><p>O estágio de cada bloco importa. Na documentação consultada, Decision Engine aparece em Produção e Decision Platform em Beta. O contrato e os limites completos ficam nas páginas técnicas.</p>`},
{slug:'autonomia-responsabilidade',title:'Autonomia com responsabilidade.',tag:'Produto e operação',art:'document',desc:'O que a máquina prepara, o que a pessoa decide e a evidência entre os dois.',source:'https://med.catalisa.app/',body:`<p>Uma automação pode responder uma mensagem, encontrar um horário e organizar um registro. Isso não torna todas as ações equivalentes. Produtos que lidam com decisões profissionais precisam tornar visível quem fez o quê e o que ainda depende de revisão.</p><h2>Rascunho é um estado.</h2><p>O Med usa uma distinção concreta: o texto preparado pela IA continua sendo rascunho enquanto o profissional não revisa e libera. O registro não ganha o mesmo significado apenas porque já existe na tela.</p><p>No Recrutamento, o parecer também passa pela aprovação do consultor. No Jurídico, a análise do caso permanece com o profissional e nada sensível sai sem um responsável.</p><h2>Uma fronteira pode virar linguagem visual.</h2><p>No produto Med, tracejado representa o rascunho e linha contínua representa o registro liberado. A interface ajuda a tornar a responsabilidade legível, usando uma convenção visual ligada ao estado real do trabalho.</p><h2>Evidência dá contexto ao resultado.</h2><p>Decision registra a versão da política usada. Biometrics descreve verificações, limiares, modelo e evidência assinada. São contextos diferentes, unidos pela necessidade de entender como um resultado foi produzido.</p><p>A proposta de arquitetura aparece justamente nessas fronteiras: autonomia para executar o que foi definido, revisão onde ela é necessária e registro para explicar o caminho.</p>`}
];
function articleCards(){return `<div class="grid3">${ESSAYS.map(e=>`<a class="article-card" href="/perspectivas/${e.slug}/">${art(e.art,'','Ilustração editorial: '+e.title)}${eyebrow(e.tag)}<h3>${e.title}</h3><p>${e.desc}</p><span class="text-link">Ler perspectiva ↗</span></a>`).join('')}</div>`}
function perspectives(){return hero('Perspectivas / Ideias em construção','Ideias que<br>merecem estrutura.','Arquitetura, composição e responsabilidade, a partir das capacidades e dos produtos da Catalisa.','plane')+section(articleCards())+section(head('Do site atual','O que a Catalisa publica.','Leituras do acervo atual de Insights. São análises de mercado publicadas pela Catalisa, não casos de clientes declarados nesta proposta.')+rows([['IA no varejo','Como o varejo brasileiro usa interfaces conversacionais para reorganizar a experiência de compra.'],['Agentes e operação','O papel dos agentes entre conversa, contexto e execução.'],['Produtos digitais','Experiências de mercado que ajudam a pensar a próxima composição.']])+actions(link('https://catalisa.io/insights/ia-conversacional-varejo-brasileiro','IA conversacional no varejo'),link('https://catalisa.io/insights/','Explore o acervo de Insights')))+section(`<div class="poster"><div class="poster-copy">${eyebrow('Uma pergunta para continuar')}<h2>Qual parte<br>do seu próximo<br>produto já existe?</h2>${link('/capacidades/','Explore as capacidades')}</div><div class="poster-art">${art('plane')}</div></div>`)}
function essay(e){return hero('Perspectivas / '+e.tag,e.title,e.desc,e.art)+section(`<article class="article-body">${eyebrow('Síntese editorial para esta proposta · baseada em conteúdo público')}<div style="margin-top:35px">${e.body}</div>${source(e.source,'Texto editorial adaptado para esta proposta a partir das capacidades e produtos públicos da Catalisa')}${e.slug==='autonomia-responsabilidade'?`<p class="small-note">Fontes complementares: <a href="https://recrutamento.catalisa.app/" target="_blank" rel="noopener">Recrutamento</a>, <a href="https://juridico.catalisa.app/" target="_blank" rel="noopener">Jurídico</a>, <a href="https://biometrics.catalisa.app/" target="_blank" rel="noopener">Biometrics</a> e <a href="https://decision.catalisa.app/" target="_blank" rel="noopener">Decision</a>.</p>`:''}</article>`)+section(head('Continue a leitura','Outras perspectivas.')+articleCards())}
function compositions(){return hero('Composições / Capacidades em contexto','A combinação<br>muda o resultado.','Explore exemplos de jornadas que conectam capacidades reais. A composição visual é ilustrativa; as páginas de cada bloco apresentam contratos e estágios.','modules')+section(composition())+section(head('Um recorte transversal','A mesma capacidade<br>em trabalhos diferentes.')+`<div class="grid3">${[['Calendar','Consulta, entrevista ou reunião. A capacidade de consultar disponibilidade e organizar a agenda aparece em contextos diferentes.','calendar'],['Rooms','Uma sala de vídeo participa da consulta médica, da conversa jurídica e da entrevista de seleção.','rooms'],['AI Engine','Texto, imagem e áudio podem ser processados por operações de IA expostas em uma API comum.','ai-engine']].map(([t,d,s])=>`<div class="tile">${art(BLOCKS.find(b=>b.slug===s)?.art||'stack','','')}<h3>${t}</h3><p>${d}</p>${actions(link('/capacidades/'+s+'/','Entenda a capacidade'))}</div>`).join('')}</div>`)+section(`<div class="grid2"><div><h2>A jornada não<br>apaga as fronteiras.</h2><p>Quem guarda um arquivo, quem avalia uma regra e quem entrega um evento continuam sendo responsabilidades distintas. A composição une essas peças para realizar um trabalho.</p>${link('/arquitetura/','Volte à arquitetura')}</div>${art('stack')}</div>`,'purple')}
function studio(){return hero('Plataforma / Studio','Da intenção<br>à especificação.','O Catalisa Studio transforma descrições em linguagem natural em agentes e automações, com refinamento da especificação e composição de fluxos.','plane')+section(`<div class="grid2"><div>${eyebrow('Como o site atual descreve o Studio')}<h2>Descreva.<br>Refine. Construa.</h2><p>O processo apresentado pela Catalisa parte do que o negócio precisa. A IA ajuda a refinar a descrição, preparar a especificação e organizar o workflow.</p>${source('https://catalisa.io/studio/')}</div>${steps([['Descreva a necessidade','Comece por uma descrição em linguagem natural ou por um template.'],['Refine com contexto','A especificação organiza requisitos, ferramentas e comportamento esperado.'],['Veja a composição','O resultado pode ser apresentado como workflow visual com os blocos conectados.'],['Execute e acompanhe','O fluxo participa da operação com os agentes e as capacidades configuradas.']])}</div>`)+section(head('Exemplo de intenção','“Quero organizar o atendimento<br>e agendar na agenda real.”','Exemplo ilustrativo de descrição. Abaixo, capacidades do catálogo que ajudam a entender esse tipo de composição.')+flow(['Descrição','Contexto','Agenda','Workflow'])+blocksSelected(['wpp-business','ai-engine','calendar','customers']))+section(`<div class="poster"><div class="poster-copy">${eyebrow('Linguagem natural encontra arquitetura')}<h2>O que você<br>descreve precisa<br>encontrar estrutura.</h2>${link('/workflows/','Veja workflows')}</div><div class="poster-art">${art('modules')}</div></div>`)}
const WORKFLOWS=[{title:'Boas-vindas ao lead',nodes:['Lead criado','Gera mensagem','Envia WhatsApp','Atualiza CRM'],desc:'Um novo lead dispara a geração de uma mensagem contextual, o envio pelo canal e o registro da interação.'},{title:'Agendamento',nodes:['Mensagem','Entende pedido','Busca agenda','Confirma horário'],desc:'A conversa organiza o pedido e consulta a disponibilidade antes de confirmar um horário.'},{title:'Onboarding',nodes:['Coleta dados','Processa documento','Verifica identidade','Registra resultado'],desc:'Documentos e identidade participam de uma jornada de entrada, preservando os papéis de cada capacidade.'}];
function workflows(){return hero('Plataforma / Workflows','O evento encontra<br>o próximo passo.','Fluxos visuais conectam gatilhos, condições e ações. O site da Catalisa apresenta execução paralela, variáveis entre blocos e acompanhamento da execução.','orbit')+section(head('Fluxos em contexto','Um caminho que<br>você consegue ler.')+`<div class="tabs" role="tablist" aria-label="Exemplos de workflow">${WORKFLOWS.map((x,i)=>`<button class="tab" role="tab" aria-selected="${!i}" data-wf="${i}">${x.title}</button>`).join('')}</div><div id="workflow-preview"></div>`)+section(`<div class="grid2"><div><h2>O que coloca<br>um fluxo em movimento?</h2><p>O site descreve gatilhos ligados a leads, mensagens, webhooks, agendamentos e execução sob demanda. A combinação depende do contexto e das capacidades configuradas.</p>${source('https://catalisa.io/workflows/')}</div>${rows([['Evento','Uma ocorrência inicia a jornada.'],['Condição','Uma regra escolhe por onde continuar.'],['Ação','Uma capacidade realiza uma operação.'],['Acompanhamento','O estado da execução ajuda a entender o resultado.']])}</div>`)+section(head('Peças da composição','Eventos, regras e canais.')+blocksSelected(['webhooks-engine','decision-engine','wpp-business','calendar']))}
function bindWorkflows(){if(!$('#workflow-preview'))return;let timer=null;const show=i=>{clearInterval(timer);const d=WORKFLOWS[i];$$('[data-wf]').forEach(b=>b.setAttribute('aria-selected',Number(b.dataset.wf)===i));$('#workflow-preview').innerHTML=`<div class="composition" style="display:block"><div class="grid2"><div><h3>${d.title}</h3><p>${d.desc}</p><button class="button outline" id="run-flow">Percorrer o exemplo →</button><p class="small-note" id="flow-state" role="status" style="margin-top:15px">Exemplo visual. Nenhuma operação real será executada.</p></div>${art(i===2?'biometrics':i===1?'med':'orbit','hero-art')}</div>${flow(d.nodes)}</div>`;$('#run-flow').addEventListener('click',()=>{let n=0;const nodes=$$('.flow-node');nodes.forEach(x=>x.classList.remove('selected'));$('#run-flow').disabled=true;timer=setInterval(()=>{nodes.forEach((x,j)=>x.classList.toggle('selected',j===n));$('#flow-state').textContent='Etapa '+(n+1)+' de '+nodes.length+': '+d.nodes[n];n++;if(n===nodes.length){clearInterval(timer);$('#run-flow').disabled=false}},650)})};$$('[data-wf]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.wf))));show(0)}
function agents(){return hero('Plataforma / Agentes IA','Contexto para<br>conversar. Ferramentas<br>para agir.','Agentes combinam instruções, conhecimento e capacidades para trabalhar em jornadas de atendimento e operação.','orbit')+section(`<div class="grid2"><div>${eyebrow('Como um agente participa')}<h2>A conversa é<br>uma das interfaces.</h2><p>O site da Catalisa descreve agentes com personalidade, ferramentas e contexto próprios, conectados a fluxos de trabalho. O trabalho pode envolver consultar uma agenda, registrar uma informação ou acionar uma capacidade.</p>${source('https://catalisa.io/ai-agents/')}</div>${steps([['Defina o papel','O agente recebe um objetivo, um contexto e limites para sua atuação.'],['Conecte conhecimento','O material da organização orienta a resposta.'],['Disponibilize ferramentas','As ações se conectam às capacidades da plataforma e aos sistemas existentes.'],['Organize a jornada','Workflows e encaminhamentos conectam a conversa ao restante da operação.']])}</div>`)+section(head('Na prática dos produtos','Autonomia tem contexto.')+`<div class="grid3">${PRODUCTS.slice(0,3).map(productCard).join('')}</div>`)+section(`<div class="editorial"><h2>Uma pessoa continua<br>responsável pelo que importa.</h2><p>Med mantém a liberação do registro com o profissional. Recrutamento exige aprovação para o parecer. Jurídico preserva a análise do caso com o advogado.</p>${link('/governanca/','Explore responsabilidade e evidência')}</div>`,'purple')}
function governance(){return hero('Arquitetura / Governança','O detalhe também<br>constrói confiança.','Permissões, isolamento, versões e evidências tornam as responsabilidades legíveis. Os contratos e limites específicos ficam documentados em cada capacidade.','document')+section(rows([['Identidade e permissões','O IAM carrega no token quem é o usuário, a qual organização pertence e quais ações pode realizar.'],['Isolamento','O catálogo descreve isolamento entre organizações e escopos próprios para as capacidades.'],['Versão e rastreabilidade','Decision Engine registra a versão da política usada em cada execução.'],['Evidência','Biometrics associa verificações e evidência assinada à decisão da sessão.']]))+section(head('Responsabilidade nos produtos','O que a interface precisa<br>deixar claro.')+`<div class="grid3">${[['Med','O texto preparado pela IA é rascunho até revisão e liberação profissional.','med'],['Recrutamento','O parecer reúne evidências e lacunas e só é publicado com aprovação.','recrutamento'],['Jurídico','O contexto vem do acervo da casa; a análise jurídica continua com o profissional.','juridico']].map(([t,d,s])=>`<div class="tile">${art(s,'','')}<h3>${t}</h3><p>${d}</p>${actions(link('/ecossistema/'+s+'/','Veja o produto'))}</div>`).join('')}</div>`)+section(`<div class="grid2"><div><h2>Estágio não é<br>um detalhe de rodapé.</h2><p>As capacidades têm estágios documentados. A própria documentação de Biometrics distingue conformidade declarada de certificação de laboratório. Esta proposta mantém essas distinções e direciona à referência completa.</p>${link('/capacidades/','Consulte os estágios no catálogo')}</div>${rows([['Produção','Estágio indicado pelo catálogo para capacidades em operação.'],['Beta','Escopo em evolução; consulte os limites publicados.'],['Alpha','Capacidade inicial; confira o contrato e a maturidade antes de adotar.']])}</div>`)+section(head('Referências','Aprofunde a base.')+blocksSelected(['iam','audit-trail','decision-engine','biometrics']))}
function developers(){return hero('Desenvolvedores / Contratos e composição','A arquitetura<br>também se lê<br>nos contratos.','Explore APIs, eventos e modelos da documentação pública. Cada capacidade explica o problema que resolve, seu escopo e como participar de uma integração.','modules')+section(`<div class="grid2"><div><h2>Comece pela<br>responsabilidade certa.</h2><p>Primeiro, encontre a capacidade. Depois, confira identidade, permissões, contrato, estágio e limites. A documentação reúne referências de API e conceitos por domínio.</p>${actions(link('https://docs.catalisa.app/blocks/','Abrir documentação','button'),link('/capacidades/','Explore o catálogo'))}</div>${rows([['Identidade','IAM, SSO e API Keys organizam usuários, organizações e credenciais.'],['Integração','Rotas e eventos pertencem ao contrato de cada bloco.'],['Composição','Escolha quem fornece os dados, quem decide, quem armazena e quem notifica.']])}</div>`)+section(`<div class="grid2"><div>${eyebrow('Um exemplo de separação de contratos')}<h2>Uma sessão.<br>Várias responsabilidades.</h2><p>No Biometrics, a sessão organiza a captura e a decisão. File Storage guarda mídia e documentos; Webhooks Engine entrega eventos. A documentação declara essas fronteiras explicitamente.</p>${link('https://docs.catalisa.app/blocks/biometrics/','Leia a arquitetura do Biometrics')}</div><div><pre aria-label="Exemplo conceitual de composição">// Composição conceitual; veja contratos na documentação\n\nIdentidade  →  IAM / API Keys\nCaptura     →  Biometrics\nArquivos    →  File Storage\nEntrega     →  Webhooks Engine</pre><p class="small-note">Diagrama textual de responsabilidades. Não é código executável nem contrato de API.</p></div></div>`)+section(head('Pontos de entrada','Explore por capacidade.')+blocksSelected(['api-keys','iam','webhooks-engine','data-store']))+section(faq([['Onde encontro endpoints e permissões?','Na referência completa de cada building block, acessível a partir das páginas do catálogo.'],['Todas as capacidades têm o mesmo estágio?','Não. O catálogo diferencia Produção, Beta e Alpha. O estágio e os limites devem ser conferidos por capacidade.'],['Este site executa chamadas reais?','Esta é uma proposta navegável do site institucional. Os exemplos de fluxo e composição são visuais. As integrações reais ficam nos produtos e na documentação oficial.']]))}
function presskit(){return hero('Marca / Press-kit','Uma identidade.<br>Muitas expressões.','Cores, tipografia e recursos oficiais da marca Catalisa. A composição visual desta proposta explora a linguagem geométrica com a base cromática publicada.','signal')+section(head('Paleta publicada','Cores que dão<br>identidade à base.')+`<div class="color-grid">${[['Roxo primário','#734B9C'],['Amarelo secundário','#FDC234'],['Grafite','#1A1D23'],['Branco','#FFFFFF']].map(([n,c])=>`<button class="color-button" data-copy="${c}" aria-label="Copiar cor ${n} ${c}"><span class="swatch" style="background:${c};color:${['#1A1D23','#734B9C'].includes(c)?'white':'#1a1d23'}">${c}</span><strong>${n}</strong></button>`).join('')}</div><p class="small-note" id="copy-state" role="status" style="margin-top:20px">Clique em uma amostra para copiar o hexadecimal.</p><p class="small-note">O laranja presente em algumas ilustrações é uma exploração complementar desta proposta. Ele não aparece na paleta do press-kit público consultado.</p>`)+section(`<div class="grid2"><div>${eyebrow('Tipografia / Inter')}<h2>Forma clara.<br>Voz consistente.</h2><p>Inter é a família indicada pelo press-kit. Nesta proposta, diferentes escalas e pesos organizam títulos editoriais, navegação e conteúdo técnico.</p></div><div><div style="font-size:70px;letter-spacing:-5px;font-weight:750">AaBbCc123</div><p>Regular · Medium · Semibold · Bold</p></div></div><div class="logo-panel"><img src="/assets/logo.svg" alt="Logotipo oficial Catalisa"></div>`)+section(head('Uso da marca','O ponto permanece.')+rows([['Proporção','Preserve a proporção entre texto e ponto. Não distorça nem rotacione o logotipo.'],['Cor','Mantenha o ponto amarelo e use a variante adequada ao fundo.'],['Respiro','O press-kit indica área livre mínima equivalente à altura do ponto ao redor do logo.'],['Arquivo','Prefira SVG para uso digital.']])+actions(link('https://catalisa.io/press-kit/','Abrir press-kit e downloads oficiais','button outline'))+source('https://catalisa.io/press-kit/'))}
function contact(){return hero('Contato / O próximo passo','Uma boa conversa<br>também constrói.','Para conhecer a plataforma ou uma aplicação específica, siga pelo canal oficial mais próximo do seu contexto.','med')+section(`<div class="contact-options"><div class="contact-card">${eyebrow('Marca e plataforma')}<h3>Converse com<br>a Catalisa.</h3><p>Conheça a base, discuta uma composição ou explore como as capacidades se aplicam à sua operação.</p>${link('https://catalisa.io/contato','Abrir contato oficial','button outline')}</div><div class="contact-card">${eyebrow('Imprensa e identidade')}<h3>Marca, recursos<br>e imprensa.</h3><p>O press-kit reúne arquivos, diretrizes de marca e o contato para imprensa.</p>${link('mailto:press@catalisa.io','press@catalisa.io','button outline')}</div></div>`)+section(head('Produtos','Já tem um contexto em mente?')+rows(PRODUCTS.map(p=>[p.name,`${p.description} <a class="text-link" href="${p.source}" target="_blank" rel="noopener">Visitar produto ↗</a>`])))}
function sources(){return hero('Recursos / Fontes','Conteúdo real.<br>Origem visível.','Esta proposta reorganiza informações públicas da Catalisa em uma experiência institucional. Os desenhos e as composições visuais são conceituais.')+section(`<div class="editorial"><h2>Como o conteúdo foi preparado.</h2><p>As descrições e os estágios dos 33 building blocks foram extraídos do catálogo e das páginas técnicas públicas. Banking e Credit também usam documentação e capturas do repositório indicado pelo usuário. Os textos dos produtos foram resumidos a partir de seus sites.</p><p>Os títulos institucionais, a navegação e os textos de ligação são uma proposta editorial. Os artigos de Perspectivas são sínteses baseadas nessas fontes, identificadas em cada página.</p><p>Não foram criados depoimentos, clientes, métricas de resultado, certificações ou preços. Os exemplos de composição e as interações deste site não executam operações da plataforma.</p></div>`)+section(head('Fontes consultadas','Aprofunde no conteúdo oficial.')+rows([['Site institucional',`${link('https://catalisa.io/','catalisa.io','')}`],['Catálogo e documentação',`${link('https://docs.catalisa.app/blocks/','docs.catalisa.app/blocks','')}`],['Studio e workflows',`${link('https://catalisa.io/studio/','Studio','')} · ${link('https://catalisa.io/workflows/','Workflows','')}`],['Agentes e Insights',`${link('https://catalisa.io/ai-agents/','Agentes IA','')} · ${link('https://catalisa.io/insights/','Insights','')}`],['Marca',`${link('https://catalisa.io/press-kit/','Press-kit','')}`],...PRODUCTS.map(p=>[p.name,link(p.source,p.domainLabel||p.slug+'.catalisa.app','')])])+`<p class="small-note" style="margin-top:25px">Consulta realizada em 15 de outubro de 2026. As fontes podem ser atualizadas depois desta versão.</p>`)}
const CORE=[['/','Home'],['/visao/','Visão'],['/arquitetura/','Arquitetura'],['/capacidades/','Capacidades'],['/composicoes/','Composições'],['/ecossistema/','Ecossistema'],['/interfaces/','Interfaces reais'],['/studio/','Studio'],['/workflows/','Workflows'],['/agentes/','Agentes IA'],['/governanca/','Governança'],['/desenvolvedores/','Desenvolvedores'],['/perspectivas/','Perspectivas'],['/press-kit/','Press-kit'],['/contato/','Contato'],['/fontes/','Fontes'],['/mapa/','Mapa do site']];
function sitemap(){return hero('Navegação / Visão completa','Todas as peças<br>desta proposta.','Navegue pelas páginas institucionais, pelos produtos e pelo catálogo completo de capacidades.')+section(`<div class="sitemap-grid"><div><h3>Marca e plataforma</h3>${CORE.filter(x=>x[0]!='/mapa/').map(([u,n])=>`<a href="${u}">${n} ↗</a>`).join('')}<h3 style="margin-top:35px">Perspectivas</h3>${ESSAYS.map(e=>`<a href="/perspectivas/${e.slug}/">${e.title} ↗</a>`).join('')}</div><div><h3>Ecossistema</h3>${PRODUCTS.map(p=>`<a href="/ecossistema/${p.slug}/">Catalisa ${p.name} ↗</a>`).join('')}<div style="margin-top:35px">${art('modules')}</div></div><div><h3>Building blocks</h3>${BLOCKS.map(b=>`<a href="${blockLink(b)}">${b.name} <span style="float:right;font-size:9px;color:var(--muted)">${b.status}</span></a>`).join('')}</div></div>`)}
function titleForRoute(){const core=CORE.find(([u])=>u.replace(/\/$/,'')===ROUTE||u===ROUTE);if(core)return core[1];const b=BLOCKS.find(b=>ROUTE==='/capacidades/'+b.slug);if(b)return b.name;const p=PRODUCTS.find(p=>ROUTE==='/ecossistema/'+p.slug);if(p)return p.name;const e=ESSAYS.find(e=>ROUTE==='/perspectivas/'+e.slug);return e?.title||'Catalisa'}
function render(){let content;const pages={'/':home,'/visao':vision,'/arquitetura':architecture,'/capacidades':catalog,'/composicoes':compositions,'/ecossistema':ecosystem,'/interfaces':interfaces,'/studio':studio,'/workflows':workflows,'/agentes':agents,'/governanca':governance,'/desenvolvedores':developers,'/perspectivas':perspectives,'/press-kit':presskit,'/contato':contact,'/fontes':sources,'/mapa':sitemap};if(pages[ROUTE])content=pages[ROUTE]();else{const b=BLOCKS.find(b=>ROUTE==='/capacidades/'+b.slug),p=PRODUCTS.find(p=>ROUTE==='/ecossistema/'+p.slug),e=ESSAYS.find(e=>ROUTE==='/perspectivas/'+e.slug);content=b?blockPage(b):p?productPage(p):e?essay(e):hero('Página não encontrada','Vamos encontrar<br>o próximo caminho.','Use o mapa do site para explorar esta proposta.')+section(link('/mapa/','Abrir mapa','button'))}document.title=titleForRoute()+' — Catalisa';$('#app').innerHTML=header()+`<main id="main" class="appear">${content}</main>`+footer();$('.menu-button').addEventListener('click',()=>{const open=$('.nav').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',open);$('.menu-button').setAttribute('aria-label',open?'Fechar menu':'Abrir menu');$('.menu-button').textContent=open?'×':'☰';document.body.classList.toggle('menu-open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.nav.open'))$('.menu-button').click()});bindComposition();bindCatalog();bindWorkflows();bindGallery();bindFaithful();$$('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);$('#copy-state').textContent=b.dataset.copy+' copiado.'}catch{$('#copy-state').textContent='Código da cor: '+b.dataset.copy}}));if(location.hash){setTimeout(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView(),100)}}
window.bootCatalisa=()=>fetch('/assets/blocks.json').then(r=>{if(!r.ok)throw Error('Catálogo indisponível');return r.json()}).then(data=>{BLOCKS=data;render()}).catch(()=>{$('#app').innerHTML='<main class="container section"><h1>Não foi possível carregar o catálogo.</h1><p>Atualize a página para tentar novamente.</p><button class="button" onclick="location.reload()">Tentar novamente</button></main>'});
function screenFeature(){return head('Da arquitetura à interface','A base ganha<br>forma na operação.','App, desktop, backoffice e mesa. Uma seleção das interfaces de referência de Banking e Credit, extraídas do repositório indicado.')+`<div class="screen-stage"><img class="desktop-shot with-phone" src="/assets/screens/bank-desktop.jpg" alt="Desktop de referência do Catalisa Banking Platform, com saldo e lançamentos de exemplo" loading="lazy"><img class="phone-shot" src="/assets/screens/bank-mobile.png" alt="Início do aplicativo Banking em aparelho de referência" loading="lazy"></div><div class="platform-links"><a href="/ecossistema/banking/">Banking Platform ↗</a><a href="/ecossistema/credit/">Credit Platform ↗</a><a href="/interfaces/">Explore as interfaces reais ↗</a></div><p class="small-note">Capturas do material de referência. Dados de demonstração. Os materiais distinguem protótipos e implementações.</p>`}
function screenCard(s){return `<button class="screen-card ${s.portrait?'portrait':''}" data-shot="${s.file}" aria-label="Ampliar ${s.title}"><img src="/assets/screens/${s.file}" alt="${s.title} — captura do material de referência" loading="lazy"><span class="caption">${eyebrow(s.product==='banking'?'Banking Platform':'Credit Platform')}<h3>${s.title} ↗</h3><p>${s.desc}</p></span></button>`}
function gallery(product=''){const shots=window.SCREENSHOTS.filter(s=>!product||s.product===product);return `<div class="screen-gallery">${shots.map(screenCard).join('')}</div>`}
function platformPage(p){const banking=p.slug==='banking';return hero('Ecossistema / Catalisa '+p.name,p.headline,p.description)+section(`<div class="screen-stage"><img class="desktop-shot ${banking?'with-phone':''}" src="/assets/screens/${banking?'bank-desktop.jpg':'credit-queue.png'}" alt="Interface de referência do ${p.name}" fetchpriority="high">${banking?'<img class="phone-shot" src="/assets/screens/bank-mobile.png" alt="App Banking em aparelho de referência">':''}</div><p class="gallery-note">${banking?'Desktop e app extraídos dos materiais de Banking Platform.':'Fila de análise extraída do material da mesa de crédito.'} Dados de exemplo; consulte o contexto de cada captura abaixo.</p>`)+section(`<div class="grid2"><div>${eyebrow('O princípio da composição')}<h2>${p.principle}</h2><p>${p.principleText}</p></div>${art(banking?'stack':'decision')}</div>`)+section(head(banking?'Canais e operação':'Da configuração ao acompanhamento',banking?'Experiências diferentes.<br>Responsabilidades compartilhadas.':'Uma esteira que<br>você consegue acompanhar.')+rows(p.features))+section(head('Uma jornada de referência','O trabalho encontra<br>seu próximo estado.')+steps(p.steps))+section(head('Interfaces do produto','Veja as peças<br>em contexto.','Clique em cada captura para ampliar. As imagens vêm do repositório indicado e preservam o conteúdo do material de referência.')+gallery(p.slug))+section(head('A base relacionada','Capacidades para<br>entender a composição.','Seleção conceitual baseada nas responsabilidades descritas nos materiais. Consulte os contratos e estágios de cada bloco.')+`<div class="grid3">${p.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div>`)+section(`<div class="grid2"><div><h2>Da referência<br>à implementação.</h2><p>${p.boundary}</p></div><div>${source(p.source,'Fonte: documentação do repositório catalisaio/wpp.bb.catalisa.io indicado pelo usuário')}${banking?`<p class="small-note">Fontes complementares: READMEs de banking-app, banking-desktop e banking-console. Os documentos registram datas e escopos diferentes; as capturas não são tratadas como comprovação de disponibilidade integral em produção.</p>`:''}${link('/interfaces/','Veja a galeria completa')}</div></div>`)+section(head('O ecossistema continua','Outras expressões<br>da mesma base.')+`<div class="products-grid">${PRODUCTS.filter(x=>x.slug!==p.slug).slice(0,3).map(productCard).join('')}</div>`)}
function interfaces(){return hero('Ecossistema / Interfaces reais','A arquitetura<br>vista por quem usa.','Uma galeria de app, desktop, console e mesa de crédito. As capturas foram selecionadas dos materiais de referência de Banking Platform e Credit Platform.')+section(`<div class="tabs screen-filter" role="tablist" aria-label="Filtrar capturas">${['Todas','App','Desktop','Console','Mesa','Política','Operação'].map((x,i)=>`<button class="tab" role="tab" aria-selected="${!i}" data-screen-filter="${x}">${x}</button>`).join('')}</div><p class="small-note">Dados de exemplo. O material de Banking reúne protótipos e telas implementadas; as capturas da mesa vêm do ambiente de demonstração. Clique para ampliar.</p><div id="screen-results">${gallery()}</div>`)+section(`<div class="comparison-band"><div>${eyebrow('Banking Platform')}<h3>O titular e a operação<br>em interfaces próprias.</h3><p>Aplicativo, desktop e console preservam contextos de uso diferentes sobre a mesma base.</p>${link('/ecossistema/banking/','Explore Banking')}</div><div>${eyebrow('Credit Platform')}<h3>A mesa liga o processo<br>do início ao acompanhamento.</h3><p>Fila, política, simulação, operações e carteira colocam o contexto de crédito à vista.</p>${link('/ecossistema/credit/','Explore Credit')}</div></div>`)}
function bindGallery(){let dialog=$('#screen-lightbox');if(!dialog){dialog=document.createElement('dialog');dialog.id='screen-lightbox';dialog.className='lightbox';dialog.innerHTML='<div class="lightbox-top"><strong id="shot-title"></strong><button type="button" id="close-shot" aria-label="Fechar imagem">Fechar ×</button></div><img id="shot-image" alt=""><p id="shot-desc"></p>';document.body.append(dialog);$('#close-shot').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})}function bindButtons(){$$('[data-shot]').forEach(b=>b.addEventListener('click',()=>{const s=window.SCREENSHOTS.find(s=>s.file===b.dataset.shot);$('#shot-title').textContent=s.title;$('#shot-image').src='/assets/screens/'+s.file;$('#shot-image').alt=s.title;$('#shot-desc').textContent=s.desc;dialog.showModal()}))}bindButtons();$$('[data-screen-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-screen-filter]').forEach(x=>x.setAttribute('aria-selected',x===b));const shots=window.SCREENSHOTS.filter(s=>b.dataset.screenFilter==='Todas'||s.type===b.dataset.screenFilter);$('#screen-results').innerHTML=`<div class="screen-gallery appear">${shots.map(screenCard).join('')}</div>`;bindButtons()}))}
